"use client";

import "../../styles/teum-base.css";
import "../../styles/components/popover.css";
import { Popover as PopoverPrimitive } from "@base-ui/react/popover";
import { cn } from "../../lib/cn";

export function Popover(props: PopoverPrimitive.Root.Props) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />;
}

export function PopoverTrigger(props: PopoverPrimitive.Trigger.Props) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />;
}

export type PopoverContentProps = PopoverPrimitive.Popup.Props &
  Pick<PopoverPrimitive.Positioner.Props, "align" | "alignOffset" | "side" | "sideOffset">;

export function PopoverContent({
  className,
  side = "bottom",
  sideOffset = 6,
  align = "start",
  alignOffset = 0,
  ...props
}: PopoverContentProps) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Positioner className="teum-positioner" side={side} sideOffset={sideOffset} align={align} alignOffset={alignOffset}>
        <PopoverPrimitive.Popup className={cn("teum-popover", className)} {...props} data-layer="flyout" />
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Portal>
  );
}

export const PopoverTitle = PopoverPrimitive.Title;
export const PopoverDescription = PopoverPrimitive.Description;

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-positioner { z-index: var(--teum-layer-flyout); }

.teum-popover { width: 278px; padding: 12px; border-radius: var(--teum-radius-overlay); background: var(--teum-bg-flyout); box-shadow: var(--teum-shadow-flyout); outline: 0; transform-origin: var(--transform-origin); transition: opacity var(--teum-enter-duration) var(--teum-ease-out), transform var(--teum-enter-duration) var(--teum-ease-out); }

.teum-popover[data-starting-style] { opacity: 0; transform: scale(0.98); }

.teum-popover[data-ending-style] { opacity: 0; transform: scale(0.99); transition-duration: var(--teum-exit-duration); }

.teum-popover { background: var(--teum-bg-flyout); }

@media (prefers-reduced-motion: reduce) {
.teum-popover {
    transition-property: opacity;
    transition-duration: var(--teum-exit-duration);
  }

.teum-popover[data-starting-style],
.teum-popover[data-ending-style] { transform: none; }
}
}
